contentRule.content:
@js:
try{
	function d(a, b) {
            b = java.md5Encode(b);
            var d = b.substring(0, 16);
            var e = b.substring(16);
            return    java.aesBase64DecodeToString(a,e,"AES/CBC/PKCS5Padding",d)}
j=result.match(/(d\("[\s\S]+"\))\);/)[1];
//jj=j.replace(/&.{3,5};/g,"");
eval(j)
} catch{java.getString("@@class.RBGsectionThree-content@p@text")
}

