ruleToc.chapterList:
@js:
list=java.getElements("article li").toArray().sort((a,b)=>a.attr("data-id")-b.attr("data-id"));
l=[];
for(i in list){
a=list[i].select("a").toArray();
l=l.concat(a)
}
l.map(x=>x)

